        store::LinkPin::Checkpoint { id } => format!("[c,{}]", enc_str(id)),
        store::LinkPin::Snapshot { blob } => format!("[s,{},{},{}]", enc_str(&blob.hash), blob.size, enc_str(&blob.media_type)),
